using System;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;
using System.Windows.Forms;
namespace PZ3D {
 sealed partial class MainForm {
  Label shootState;TextBox shootEvidence;string shootBackup;
  void AddShootClientPage(TabControl tabs){var page=Page(tabs,"射击客户端实验");shootState=new Label{AutoSize=true,MaximumSize=new Size(1000,0),Margin=new Padding(8)};page.Controls.Add(shootState);AddText(page,"Shoot to Thrill（原 I SEE THEM）· 多人版客户端测试\n服务器不作任何改动。服务器无此模块时，代码有保留原生战斗的兜底；瞄准、枪械模型和命中效果需要你实测，不能当成完整弹道系统。\n只启用 ShootToThrillMultiplayer，不混开单人版、旧版、Recoil & ADS 或 True Ballistics。先在首页安装 / 启用 3D 与 Buddy。加入服务器可能重建模组列表；本工具不绕过服务器校验、不强制注入。");
   var actions=new FlowLayoutPanel{AutoSize=true,WrapContents=true,MaximumSize=new Size(1000,0)};actions.Controls.Add(Button("安装 / 启用客户端测试",()=>{if(MessageBox.Show(this,"这是客户端实验，不修改服务器，不保证第一人称命中正确。\n会从作者工坊下载缺失文件并备份修改本地 default.txt；首次需你确认 Java 授权。\n发生报错、命中异常或服务器拒绝时关闭实验。是否继续？","射击客户端测试",MessageBoxButtons.OKCancel,MessageBoxIcon.Warning)==DialogResult.OK)Run(EnableShootClient,"正在准备射击多人版客户端测试");}));actions.Controls.Add(Button("关闭射击测试",()=>Run(()=>{var store=new ShootClient();string result=store.Disable(GetEngine());RememberShootBackup(store);return result;})));actions.Controls.Add(Button("检查射击模组更新",()=>Run(()=>{GetEngine().Guard();DownloadSelected(new[]{ShootClient.Item});return "已核对射击模组版本；没有自动启用。更新后完全重启游戏并核对 Java 授权。";})));actions.Controls.Add(Button("安装进服开镜恢复桥接",()=>{if(MessageBox.Show(this,"这会另加本工具的 Java 初始化桥接和启动参数，不改作者 JAR 或服务器。\n仅尝试本地开镜；原版/服务器命中规则保留。\n目前只支持已核实的射击 JAR，开镜渲染与瞄具资源尚待实测。需完全退出游戏。是否继续？","本地开镜恢复实验",MessageBoxButtons.OKCancel,MessageBoxIcon.Warning)==DialogResult.OK)Run(()=>{var bridge=new PresentationBridge();string result=bridge.Enable(GetEngine(),Path.Combine(GetEngine().Workshop,ShootClient.Item.ToString()));if(bridge.LastBackup!=null){shootBackup=bridge.LastBackup;File.WriteAllText(Path.Combine(data,"shoot-backup-path.txt"),shootBackup);}return result;});}));actions.Controls.Add(Button("关闭开镜恢复桥接",()=>Run(()=>new PresentationBridge().Disable(GetEngine()))));actions.Controls.Add(Button("读取最近射击日志",ReadShootEvidence));page.Controls.Add(actions);
   AddButton(page,"打开备份 / 人工恢复说明",()=>{string pointer=Path.Combine(data,"shoot-backup-path.txt");if(shootBackup==null&&File.Exists(pointer))shootBackup=File.ReadAllText(pointer);if(shootBackup==null||!Directory.Exists(shootBackup))throw new Exception("尚无射击配置操作备份。");Links.Open(shootBackup);});AddButton(page,"作者工坊与说明",()=>Links.Open("https://steamcommunity.com/sharedfiles/filedetails/?id=3813032735"));AddText(page,"测试：退出游戏 → 启用此入口 → Steam 正常启动 → 仅批准已确认的射击 Java 文件 → 进入原服务器 → 用手枪机瞄、步枪红点分别测试。Ctrl+V 切换腰射 / 精瞄（以游戏实际绑定为准）。首次对比先关闭实验 DLSS 和画中画镜。\n日志 waiting / unavailable 表示服务器握手未完成；ready 只代表协议匹配，不代表自定义伤害正确。看到 no server reply / native combat remains active 是原生战斗兜底证据。\n关闭只移除测试的默认模组项，保留工坊文件、个人校准及基础 3D。射击扩展版权归 haru，前置版权归各原作者；工具不内置或修改作者 JAR。日志窗口显示的是磁盘记录，不冒充游戏实时内存状态。\n进服后只剩 Java、Lua 没加载时，可退出游戏再安装“进服开镜恢复桥接”。它只初始化本地表现，不激活自定义战斗；首先关画中画镜，不保证完整瞄具效果。日志 [ORANGE-ADS] initialized 仅证明初始化调用，stopped 表示已因版本或接口问题停用。");shootEvidence=new TextBox{Width=1000,Height=220,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Both,Text="尚未读取日志。已写入配置不代表进入服务器后成功加载。"};page.Controls.Add(shootEvidence);Theme(page);UpdateShootState();}
  void RememberShootBackup(ShootClient store){if(store.LastBackup!=null){shootBackup=store.LastBackup;File.WriteAllText(Path.Combine(data,"shoot-backup-path.txt"),shootBackup);}}
  string EnableShootClient(){var engine=GetEngine();engine.Guard();if(!ShootClient.BaseReady(engine))throw new Exception("请先安装基础 3D 与 Buddy。");string source=InstallWorkflow.Source(engine,ShootClient.Item);try{ShootClient.Validate(source);ReportDownload(100,"枪械扩展文件完整，复用本地文件；最新版请点检查更新");}catch{source=DownloadSelected(new[]{ShootClient.Item})[ShootClient.Item];}var store=new ShootClient();string result=store.Enable(engine,source);RememberShootBackup(store);return result+"\r\n服务器未修改。重启游戏并进服后验证实际开镜效果。";}
  void UpdateShootState(){if(shootState==null)return;try{var engine=GetEngine();shootState.Text="枪械瞄准："+(ShootClient.Enabled(engine)?"已配置":"未安装 / 已卸载")+"　联机开镜补丁："+(new PresentationBridge().Enabled(engine)?"已配置":"未安装 / 已卸载")+"　游戏内中文："+(ChinesePatch.Enabled(engine)?"已配置":"未安装 / 已卸载")+"\n使用：安装后重启 → O 开第一人称 → 右键瞄准；Ctrl+V 切换腰射/精瞄。中文需游戏语言为简体中文并批准 laoyu.javacn。"+"\n卸载只作用于勾选项；只卸载枪械时取消其他勾选。配置完成不代表本次进服已生效。不改服务器或 GUNS OF MARZ 内容。";}catch(Exception e){shootState.Text=e.Message;}}
  void ReadShootEvidence(){string file=Path.Combine(UserDir(),"console.txt");if(!File.Exists(file)){shootEvidence.Text="尚无 console.txt。请启动游戏并进入服务器后再读取。";return;}string text;using(var stream=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete))using(var reader=new StreamReader(stream))text=reader.ReadToEnd();var lines=text.Split('\n').Where(l=>Regex.IsMatch(l,@"(?i)ORANGE-ADS|STT-MP-INPUT|STT-MP-SETTINGS|IST-NET|ISeeThem|ShootToThrill|iseethem|server bridge|native combat|native shot observer|route-unavailable")).ToArray();var selected=lines.Where(l=>!l.Contains("[ORANGE-ADS]")).Reverse().Take(60).Reverse().Concat(lines.Where(l=>l.Contains("[ORANGE-ADS]")).Reverse().Take(40).Reverse());shootEvidence.Text="最近磁盘日志（可能属于旧游戏轮次，不是当前加载成功证明）\r\n"+file+"\r\n修改时间："+File.GetLastWriteTime(file)+"\r\n\r\n"+(selected.Any()?string.Join("\r\n",selected):"未找到射击模组证据。可能尚未加载、Java 未批准，或进服后被服务器模组列表替换。不要据此宣称功能已启用。");}
 }
}
